"""Terminal workflow; API client prints predictions generated by the saved model."""
import argparse
import json
import os
from pathlib import Path
import sys
import pandas as pd
import requests
from nfl.features import training_table
from nfl.storage import Store

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    for name in ['features', 'train']:
        p = sub.add_parser(name)
        p.add_argument('--cache', action='store_true', help='explicit offline experiment from verified source; default is storage')
        if name == 'train':
            p.add_argument('--test-season', type=int, default=2024)
    sub.add_parser('export')
    sub.add_parser('counts')
    p = sub.add_parser('evaluate')
    p.add_argument('--url', default='http://127.0.0.1:8000')
    p = sub.add_parser('predict')
    p.add_argument('--season', type=int, required=True)
    p.add_argument('--week', type=int, required=True)
    p.add_argument('--home')
    p.add_argument('--away')
    p.add_argument('--url', default='http://127.0.0.1:8000')
    args = parser.parse_args()
    try:
        if args.command in ['features', 'train']:
            if args.cache:
                from nfl.source import cached_games
                games = cached_games()
            else:
                store = Store()
                try:
                    games = store.games()
                finally:
                    store.close()
            table = training_table(games)
            Path('artifacts').mkdir(exist_ok=True)
            table.to_csv('artifacts/training.csv', index=False)
            table.head(10).to_csv('data/training_sample.csv', index=False)
            if args.command == 'train':
                from nfl.model import train
                metadata = train(table, args.test_season, cache=args.cache)
                Path('artifacts/evaluation.json').write_text(json.dumps(metadata, indent=2) + '\n')
                print(json.dumps(metadata, indent=2))
            else:
                print(f'Wrote {len(table)} feature rows to artifacts/training.csv')
        elif args.command in ['export', 'counts']:
            store = Store()
            try:
                if args.command == 'export':
                    store.export('data/staging')
                print(json.dumps(store.counts(), indent=2))
            finally:
                store.close()
        elif args.command == 'evaluate':
            response = requests.get(args.url + '/evaluation', timeout=30)
            response.raise_for_status()
            print(json.dumps(response.json(), indent=2))
        else:
            if bool(args.home) != bool(args.away):
                raise ValueError('Supply both --home and --away, or neither for the whole week')
            if args.home:
                contexts = [dict(home_team=args.home, away_team=args.away, season=args.season, week=args.week)]
            else:
                from nfl.source import cached_games
                contexts = [{k: g[k] for k in ['home_team', 'away_team', 'season', 'week']} for g in cached_games() if g['season'] == args.season and g['week'] == args.week]
                if not contexts:
                    raise ValueError('No games for that week in the verified snapshot')
            for context in contexts:
                response = requests.post(args.url + '/predict', json=context, timeout=60)
                if not response.ok:
                    raise ValueError(f'API {response.status_code}: {response.text}')
                g = response.json()
                print(f"{g['game_id']} | {g['gameday']} | {g['away_team']} at {g['home_team']} | winner {g['predicted_winner']} | estimated probability {g['estimated_win_probability']:.1%} | {g['model_version']} | trained through {g['training_cutoff']} | {g['context']}")
    except Exception as error:
        print(f'Error: {error}', file=sys.stderr)
        raise SystemExit(1)

if __name__ == '__main__':
    main()
